<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;
use App\Core\Database;
use App\Services\DanceCupScoringService;
Auth::requireAdmin();
$test=(string)($_GET['data_mode']??'')==='test';
if($test&&!Auth::isSuperAdmin()){http_response_code(403);exit('Super Admin access required.');}
$workflow=(string)($_GET['workflow']??'');
$modes=[
    'manual'=>['Manual Scoring','category.php','Open Manual Sheet','dark','✎','Contestants, judges, marks, calculations, checkpoints and submission.'],
    'automatic'=>['Automatic Scoring','automation.php','Open Automation','primary','⚙','Secure judge links, submission monitoring and emergency manual fallback.'],
    'projection'=>['Live Projection','projection-control.php','Open Projection Control','danger','▣','Contestant calls, holding screens, progress, results and podium.'],
];
if(!isset($modes[$workflow])){header('Location: ./'.($test?'?data_mode=test':''),true,303);exit;}
$pdo=Database::connection();
DanceCupScoringService::ensureWorkspaceTables($pdo,$test);
$t=DanceCupScoringService::tables($test);
$q=$pdo->query("SELECT c.id,c.category_name,c.dance_style,c.competition_level,c.entry_type,c.round_name,c.status,e.name event_name,e.event_date FROM {$t['competitions']} c JOIN {$t['events']} e ON e.id=c.event_id WHERE e.status<>'archived' ORDER BY e.event_date DESC,e.id DESC,c.category_name,c.id");
$categories=$q->fetchAll();
[$label,$route,$actionLabel,$colour,$icon,$description]=$modes[$workflow];
$suffix=$test?'&data_mode=test':'';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($label)?> | Dance Cup</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../../public/css/scoring-premium.css?v=358" rel="stylesheet"><script defer src="../../public/assets/js/bdc-theme.js?v=325"></script><style>body{background:#f4f6f9}.workflow-shell{max-width:1350px}.workflow-hero{border:0;border-radius:24px;background:linear-gradient(135deg,#101c35,#5b1833);color:#fff;box-shadow:0 18px 44px rgba(15,23,42,.17)}.workflow-icon{display:grid;place-items:center;width:62px;height:62px;border-radius:18px;background:rgba(255,255,255,.13);font-size:1.8rem}.category-card{border:1px solid #e0e5ec;border-radius:18px;box-shadow:0 10px 28px rgba(15,23,42,.07)}.category-card .btn{min-height:46px;font-weight:800}.event-name{color:#8b2948;font-weight:800}.meta{display:flex;gap:.45rem;flex-wrap:wrap}.meta span{padding:.3rem .55rem;border-radius:999px;background:#eef2f7;font-size:.78rem;font-weight:700}</style></head><body><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="./<?=$test?'?data_mode=test':''?>">BDC Dance Cup</a><a class="btn btn-outline-light btn-sm" href="../">Dashboard</a></div></nav><main class="container workflow-shell py-4"><section class="workflow-hero p-4 p-lg-5 mb-4"><div class="d-flex align-items-center gap-3"><div class="workflow-icon"><?=e($icon)?></div><div><div class="text-uppercase small fw-bold text-warning"><?=$test?'Test only · ':''?>Dance Cup Workflow</div><h1 class="h2 mb-1"><?=e($label)?></h1><p class="mb-0 opacity-75"><?=e($description)?></p></div></div></section><div class="d-flex justify-content-between align-items-center gap-2 flex-wrap mb-3"><div><h2 class="h4 mb-1">Choose Dance Cup Category</h2><p class="text-muted mb-0">Only Dance Cup categories are listed. Jack &amp; Jill remains separate.</p></div><div class="d-flex gap-2"><a class="btn btn-outline-secondary" href="./<?=$test?'?data_mode=test':''?>">Change Workflow</a><a class="btn btn-warning" href="index.php?workflow=manual<?=$suffix?>">Manage Events &amp; Categories</a></div></div><div class="row g-3"><?php foreach($categories as $c):?><div class="col-md-6 col-xl-4"><article class="card category-card h-100"><div class="card-body p-4 d-flex flex-column"><div class="event-name small mb-2"><?=e($c['event_name'])?></div><h3 class="h5"><?=e($c['category_name'])?></h3><div class="meta mb-4"><span><?=e(ucwords(str_replace('_',' ',$c['dance_style'])))?></span><span><?=e(ucwords(str_replace('_',' ',$c['competition_level'])))?></span><span><?=e(ucfirst($c['round_name']))?></span><span><?=e(ucfirst($c['status']))?></span></div><a class="btn btn-<?=e($colour)?> mt-auto" href="<?=e($route)?>?id=<?=(int)$c['id']?><?=$suffix?>"><?=e($actionLabel)?></a></div></article></div><?php endforeach;?><?php if(!$categories):?><div class="col-12"><div class="card category-card"><div class="card-body text-center p-5"><h3 class="h5">No Dance Cup categories yet</h3><p class="text-muted">Create an event and category before opening this workflow.</p><a class="btn btn-warning" href="index.php?workflow=manual<?=$suffix?>">Create Dance Cup Category</a></div></div></div><?php endif;?></div></main></body></html>
